<?php
// QR có chữ ký, đổi theo chu kỳ 20 giây; quyền điền phiếu chỉ dành cho phiên vừa quét.
function attendance_defaults(&$st){if(!isset($st['attendance']))$st['attendance']=array('sessions'=>array());}
function attendance_identity($school,$name){return hash('sha256',$school."\n".$name);}
function attendance_expected($st){$rows=array();foreach(portal_directory($st) as $u)foreach($u['people'] as $p){if(empty($p['name']))continue;$key=attendance_identity($u['school'],$p['name']);$rows[$key]=array('name'=>$p['name'],'school'=>$u['school'],'role'=>$p['role']);}return $rows;}
function attendance_signature($session,$slot){global $config;return hash_hmac('sha256',$session['id'].'|'.$session['nonce'].'|'.$slot,$config['setup_key']);}
function attendance_proof($session,$now){$slot=(int)floor($now/20);return array('session'=>$session['id'],'slot'=>$slot,'signature'=>attendance_signature($session,$slot),'expires_at'=>($slot+1)*20,'server_time'=>$now,'revision'=>isset($session['revision'])?$session['revision']:1);}
function attendance_valid_proof($session,$input,$now){return $session['open']&&isset($input['slot'],$input['signature'])&&is_int($input['slot'])&&$input['slot']===(int)floor($now/20)&&is_string($input['signature'])&&hash_equals(attendance_signature($session,$input['slot']),$input['signature']);}
function attendance_grant($st){$g=isset($_SESSION['attendance_grant'])?$_SESSION['attendance_grant']:null;if(!$g||$g['expires']<=time()||!isset($st['attendance']['sessions'][$g['session']]))return null;$s=$st['attendance']['sessions'][$g['session']];if(!$s['open']||$s['nonce']!==$g['nonce'])return null;return array('session'=>$s['id'],'title'=>$s['title'],'date'=>$s['date'],'expires_at'=>$g['expires']);}
function attendance_need_grant($st){$g=attendance_grant($st);if(!$g)fail('Quét mã QR đang hiển thị của buổi tập huấn để điểm danh. Mã cũ hoặc buổi đã đóng không còn hiệu lực.',409);return $g;}
function attendance_record(&$st,$pid,$grant){$s=&$st['attendance']['sessions'][$grant['session']];$p=$st['participants'][$pid];$key=attendance_identity($p['school'],$p['name']);if(!isset($s['expected'][$key]))$s['expected'][$key]=array('name'=>$p['name'],'school'=>$p['school'],'role'=>$p['role']);if(!isset($s['records'][$pid]))$s['records'][$pid]=array('time'=>gmdate('c'),'name'=>$p['name'],'school'=>$p['school'],'role'=>$p['role']);unset($_SESSION['attendance_grant']);}
function attendance_summary($st,$is_admin){$pid=isset($_SESSION['participant'])?$_SESSION['participant']:'';$out=array();foreach($st['attendance']['sessions'] as $s){$mine=isset($s['records'][$pid])?$s['records'][$pid]['time']:null;$v=array('id'=>$s['id'],'title'=>$s['title'],'date'=>$s['date'],'open'=>$s['open'],'count'=>count($s['records']),'eligible'=>count($s['expected']),'mine'=>$mine,'revision'=>isset($s['revision'])?$s['revision']:1);if($is_admin){$rows=$s['expected'];foreach($rows as &$row){$row['present']=false;$row['time']=null;$row['phone']='';}unset($row);foreach($s['records'] as $id=>$r){$key=attendance_identity($r['school'],$r['name']);$rows[$key]=array('name'=>$r['name'],'school'=>$r['school'],'role'=>$r['role'],'present'=>true,'time'=>$r['time'],'phone'=>isset($st['participants'][$id]['phone'])?$st['participants'][$id]['phone']:'');}$v['rows']=array_values($rows);$v['absent']=count(array_filter($rows,function($r){return !$r['present'];}));}$out[]=$v;}return array('sessions'=>$out,'grant'=>attendance_grant($st),'server_time'=>time());}
function attendance_actions($action,$input){
 if($action==='portal_scan')return with_state(function(&$st)use($input){unset($_SESSION['attendance_grant']);$id=portal_field($input,'session',100);if(!isset($st['attendance']['sessions'][$id])||!attendance_valid_proof($st['attendance']['sessions'][$id],$input,time()))fail('Mã QR đã hết hạn hoặc buổi điểm danh đã đóng. Vui lòng quét mã mới đang hiển thị.',409);$s=$st['attendance']['sessions'][$id];$_SESSION['attendance_grant']=array('session'=>$id,'nonce'=>$s['nonce'],'expires'=>time()+600);return array('ok'=>true,'grant'=>attendance_grant($st));},false);
 need_admin();
 if($action==='portal_attendance_qr')return with_state(function(&$st)use($input){$id=portal_field($input,'session',100);if(!isset($st['attendance']['sessions'][$id])||!$st['attendance']['sessions'][$id]['open'])fail('Mở buổi điểm danh trước khi tạo QR.',409);return attendance_proof($st['attendance']['sessions'][$id],microtime(true));},false);
 return with_state(function(&$st)use($action,$input){$sessions=&$st['attendance']['sessions'];
  if($action==='portal_attendance_create'){$title=portal_field($input,'title',160);$date=portal_field($input,'date',10);if($title==='')fail('Nhập tên buổi tập huấn.',400);if(!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/',$date,$m)||!checkdate((int)$m[2],(int)$m[3],(int)$m[1]))fail('Chọn ngày tập huấn hợp lệ.',400);if(count($sessions)>=100)fail('Đã đạt giới hạn 100 buổi.',409);foreach($sessions as &$s){$s['open']=false;$s['revision']=(isset($s['revision'])?$s['revision']:1)+1;}unset($s);$id='attendance-'.substr(token(),0,16);$sessions[$id]=array('id'=>$id,'title'=>$title,'date'=>$date,'open'=>true,'revision'=>1,'nonce'=>token(),'expected'=>attendance_expected($st),'records'=>array(),'created'=>gmdate('c'));audit($st,'Tạo buổi điểm danh: '.$title);return array('ok'=>true,'id'=>$id);}
  if($action==='portal_attendance_control'){$id=portal_field($input,'session',100);if(!isset($sessions[$id]))fail('Không có buổi điểm danh này.',404);$op=portal_field($input,'op',10);if(!in_array($op,array('open','close'),true))fail('Thao tác không hợp lệ.',400);if($op==='open'){foreach($sessions as &$s){$s['open']=false;$s['revision']=(isset($s['revision'])?$s['revision']:1)+1;}unset($s);}$sessions[$id]['open']=$op==='open';$sessions[$id]['nonce']=token();$sessions[$id]['revision']=(isset($sessions[$id]['revision'])?$sessions[$id]['revision']:1)+1;audit($st,'Buổi điểm danh: '.$op.' '.$sessions[$id]['title']);return array('ok'=>true);}
  fail('Thao tác không hợp lệ.',404);
 },true);
}
